import { OrderRepository } from '../repositories/order-repository.js';

export function listOrdersForUser(userId, callback) {
  new OrderRepository().findByUser(userId).then(
    (orders) => callback(null, orders),
    callback,
  );
}

export function totalPaidCents(callback) {
  new OrderRepository().findPaid().then(
    (orders) => callback(null, orders.reduce((sum, order) => sum + order.total_cents, 0)),
    callback,
  );
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.deepEqual(orders.map((order) => order.id), [10, 11]);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('listOrdersForUser returns an empty array for an unknown user', (t, done) => {
  listOrdersForUser(999, (err, orders) => {
    assert.equal(err, null);
    assert.deepEqual(orders, []);
    done();
  });
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 14600);
    done();
  });
});
import { query } from '../db.js';

export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findQuotes() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'quote' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
